We'll replace draw function with new.

New draw function:

```
function draw() {
  // Clear with space background
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw stars
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Draw planet with gradient
  const planetGrad = ctx.createRadialGradient(
    planet.x,
    planet.y,
    planet.r * 0.2,
    planet.x,
    planet.y,
    planet.r
  );
  planetGrad.addColorStop(0, '#6ee7b7');
  planetGrad.addColorStop(1, planet.color);
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fillStyle = planetGrad;
  ctx.fill();

  // Draw satellite with glow
  const satX = planet.x + Math.cos(satellite.angle) * satellite.distance;
  const satY = planet.y + Math.sin(satellite.angle) * satellite.distance;
  ctx.save();
  ctx.shadowColor = 'rgba(255,215,0,0.7)';
  ctx.shadowBlur = 12;
  ctx.beginPath();
  ctx.arc(satX, satY, satellite.r, 0, Math.PI * 2);
  ctx.fillStyle = satellite.color;
  ctx.fill();
  ctx.restore();

  // Draw orbs with gradient
  for (const o of orbs) {
    const grad = ctx.createRadialGradient(o.x, o.y, 0, o.x, o.y, orbRadius);
    grad.addColorStop(0, '#a7f3d0');
    grad.addColorStop(1, '#10b981');
    ctx.beginPath();
    ctx.arc(o.x, o.y, orbRadius, 0, Math.PI * 2);
    ctx.fillStyle = grad;
    ctx.fill();
  }

  // Draw score
  ctx.fillStyle = '#fff';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: ' + score, 10, 20);
}
```

